    surface_index,
    surface_row0.x,
    surface_row0.y,
    surface_row3.y,
    vertex_offset,
    vertex_count,
    triangle_offset,
    triangle_count,
    render_order,
    transparency_class_id,
    depth_write_flag,
    select(0.0, 1.0, surface_is_active),
    bounds_center,
    bounds_radius_m
